/// One thing the server sent.
#[derive(Debug)]
pub enum ServerEvent {
    Diagnostics(lsp_types::PublishDiagnosticsParams),
    Response { id: i64, method: &'static str, result: Result<serde_json::Value, LspError> },
    Request { id: serde_json::Value, method: String, params: serde_json::Value },
    Log(String),
}

impl LspClient {
    /// Every queued body as an event, oldest first. Returns at once when nothing is queued.
    pub fn poll(&mut self) -> Vec<ServerEvent>;
}
